from itertools import product
def models(n):
    for P in product([0, 1], repeat=n):
        for bits in product([0, 1], repeat=n * n):
            R = [bits[i * n:(i + 1) * n] for i in range(n)]
            if any(P[x] and not any(R[x][y] and P[y] for y in range(n)) for x in range(n)): continue  # S1
            if any(R[x][y] and R[y][x] for x in range(n) for y in range(n)): continue                 # S2
            if not any(P): continue                                                                   # S3
            yield P, R
cyc3 = lambda P, R, n: any(R[x][y] and R[y][z] and R[z][x] for x in range(n) for y in range(n) for z in range(n))
tests = {'A': lambda P, R, n: sum(P) >= 2, 'B': lambda P, R, n: sum(P) >= 3,
         'C': lambda P, R, n: sum(P) >= 4, 'D': cyc3}
for n in range(1, 5):
    ms = list(models(n))
    print(n, len(ms), {k: all(f(P, R, n) for P, R in ms) for k, f in tests.items()})
# n=3: C fails (3-cycle model); n=4: D fails (4-cycle model); A, B hold in every model found
